styl:
.white-bg.b-affsystem-text-48 {  background:#fff  }
.b-affsystem-text-48 .min-text, .b-affsystem-text-48 .text {  font-family:Helvetica!important;color:#2e3851;letter-spacing:0  }
.b-affsystem-text-48 .text {  font-weight:400;font-size:16px;line-height:26px  }
.b-affsystem-text-48 .min-text {  font-size:14px;line-height:22px  }
.b-affsystem-text-48 .big-text, .b-affsystem-text-48 .subtitle, .b-affsystem-text-48 b, .b-affsystem-text-48 p.warning, .b-affsystem-text-48 p.warning .upper {  font-family:Helvetica!important  }
.b-affsystem-text-48 .big-text {  font-weight:700!important;font-size:16px!important  }
.b-affsystem-text-48 .text.italic {  font-style:italic  }
.b-affsystem-text-48 .text.list {  display:list-item  }
.b-affsystem-text-48 .pb5 {  padding-bottom:5px  }
.b-affsystem-text-48 .pb15 {  padding-bottom:15px!important  }
.b-affsystem-text-48 .pt15 {  padding-top:15px  }
.b-affsystem-text-48 .pt25 {  padding-top:25px  }
.bg-bord-lr.b-affsystem-text-48 {  border-left:1px solid #e9ebea;border-right:1px solid #e9ebea  }
.bg-bord-top.b-affsystem-text-48 {  border-top:1px solid #e9ebea  }
.br-top.b-affsystem-text-48 {  border-radius:5px 5px 0 0  }
.b-affsystem-text-48 .text a {  font-family:Helvetica!important;text-decoration:none!important;color:#01c689!important  }
.b-affsystem-text-48 .border-green {  border:solid 1px #01c689;border-radius:5px;background:#f4faf8;padding:12px 15px  }
.b-affsystem-text-48 .green-number, .b-affsystem-text-48 .list-item {  font-family:Helvetica!important  }
.b-affsystem-text-48 .green-number {  font-weight:700;font-size:14px;letter-spacing:1px;text-align:center;background:#01c689;border-radius:3px;padding:3px 12px;vertical-align:top;margin-right:10px;color:#fff  }
.b-affsystem-text-48 .list-item {  background:url("https://static.cdnpub.info/files/storage/public/5e/8d/aa6a28c720a9i1g3f9/Oval Copy 3.png") left top 8px no-repeat;background-size:10px;padding-left:20px;color:#2e3851  }
